def first_or(xs: list[int], default: int) -> int:
    """Return the first element of xs, or default if xs is empty."""
    return xs[0] if xs else default


def test_first_or_non_empty() -> None:
    assert first_or([10, 20, 30], default=0) == 10
    assert first_or([42], default=-1) == 42


def test_first_or_empty() -> None:
    assert first_or([], default=0) == 0
    assert first_or([], default=-99) == -99

